BEGIN;
ALTER TABLE swot_campaigns ADD COLUMN collection_revision smallint NOT NULL DEFAULT 1 CHECK(collection_revision IN (1,2));
ALTER TABLE swot_campaigns ALTER COLUMN collection_revision SET DEFAULT 2;
CREATE TABLE swot_participant_contexts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),campaign_id uuid NOT NULL REFERENCES swot_campaigns(id),user_id uuid NOT NULL REFERENCES profiles(id),team_id uuid REFERENCES teams(id),label text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX swot_participant_context_unique ON swot_participant_contexts(campaign_id,user_id,coalesce(team_id,'00000000-0000-0000-0000-000000000000'::uuid));
ALTER TABLE swot_submissions ADD COLUMN completion_type text NOT NULL DEFAULT 'completed' CHECK(completion_type IN ('completed','exception')),ADD COLUMN authorized_by uuid REFERENCES profiles(id),ADD COLUMN exception_reason text;
ALTER TABLE swot_submissions ADD CHECK(completion_type<>'exception' OR (authorized_by IS NOT NULL AND length(trim(exception_reason))>0));
ALTER TABLE swot_contributions ADD COLUMN imported_by uuid REFERENCES profiles(id),ADD COLUMN import_batch_id uuid;
ALTER TABLE swot_items ADD COLUMN contribution_scope text CHECK(contribution_scope IN ('own_team','organization','other_team')),ADD COLUMN team_id uuid REFERENCES teams(id);
CREATE TRIGGER participant_context_immutable BEFORE UPDATE OR DELETE ON swot_participant_contexts FOR EACH ROW EXECUTE FUNCTION quality_immutable();
ALTER TABLE swot_participant_contexts ENABLE ROW LEVEL SECURITY;
CREATE POLICY company_read ON swot_participant_contexts FOR SELECT TO authenticated USING(session_valid() AND (access_admin() OR organization_id=my_organization()) AND has_module('strategy'));
REVOKE ALL ON swot_participant_contexts FROM PUBLIC,anon,authenticated;
GRANT SELECT ON swot_participant_contexts TO authenticated;
CREATE TABLE auth_password_resets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES profiles(id),token_hash text NOT NULL UNIQUE,session_version integer NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_recovery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),outcome text NOT NULL CHECK(outcome IN ('pending','sent','unavailable','failed','unknown')));
CREATE INDEX auth_recovery_recent ON auth_recovery_attempts(email_hash,created_at);
REVOKE ALL ON auth_password_resets,auth_recovery_attempts FROM PUBLIC,anon,authenticated;
CREATE TRIGGER ppt_structure_guard BEFORE UPDATE OR DELETE ON ppt_templates FOR EACH ROW EXECUTE FUNCTION strategy_structure_guard();
CREATE TRIGGER framework_structure_guard BEFORE UPDATE OR DELETE ON frameworks FOR EACH ROW EXECUTE FUNCTION strategy_structure_guard();
NOTIFY pgrst,'reload schema';
COMMIT;
